}

/// Log verbosity levels.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum LogLevel {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

/// Log output encoding format.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
