## `src/validator.rs` — Configuration Validation

```rust
use crate::config::{Config, Environment};
use crate::error::{ConfigError, Result};

/// Validates a fully-loaded configuration, returning aggregated errors.
pub fn validate(config: &Config) -> Result<()> {
    let mut errors: Vec<String> = Vec::new();

    validate_server(config, &mut errors);
    validate_database(config, &mut errors);
    validate_logging(config, &mut errors);
    validate_production_requirements(config, &mut errors);

    match errors.len() {
        0 => Ok(()),
        1 => Err(ConfigError::Validation(errors.remove(0))),
        _ => Err(ConfigError::MultipleValidation(errors)),
    }
}

fn validate_server(config: &Config, errors: &mut Vec<String>) {
    if config.server.port == 0 {
        errors.push("server.port must be > 0".into());
    }

    if config.server.max_connections == 0 {
        errors.push("server.max_connections must be > 0".into());
    }

    if config.server.worker_threads == 0 {
        errors.push("server.worker_threads must be > 0".into());
    }

    if config.server.host.is_empty() {
        errors.push("server.host must not be empty".into());
    }

    // TLS: both or neither
    match (&config.server.tls_cert_path, &config.server.tls_key_path) {
        (Some(_), None) => {
            errors.push("server.tls_key_path is required when tls_cert_path is set".into());
        }
        (None, Some(_)) => {
            errors.push("server.tls_cert_path is required when tls_key_path is set".into());
        }
        _ => {}
    }
}

fn validate_database(config: &Config, errors: &mut Vec<String>) {
    if config.database.url.is_empty() {
        errors.push("database.url must not be empty".into());
    }

    if config.database.pool_min > config.database.pool_max {
        errors.push(format!(
            "database.pool_min ({}) must be <= pool_max ({})",
            config.database.pool_min, config.database.pool_max
        ));
    }

    if config.database.pool_max == 0 {
        errors.push("database.pool_max must be > 0".into());
    }

    if config.database.connection_timeout_secs == 0 {
        errors.push("database.connection_timeout_secs must be > 0".into());
    }
}

fn validate_logging(config: &Config, errors: &mut Vec<String>) {
    if let Some(ref path) = config.logging.file_path {
        if path.is_empty() {
            errors.push("logging.file_path must not be empty when specified".into());
        }
    }
}

fn validate_production_requirements(config: &Config, errors: &mut Vec<String>) {
    if config.app.environment == Environment::Production {
        if config.app.debug {
            errors.push("app.debug must be false in production".into());
        }

        if config.server.tls_cert_path.is_none() {
            errors.push("TLS must be configured in production".into());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::*;

    /// Helper: start from valid defaults and tweak fields per-test.
    fn valid_config() -> Config {
        Config::default()
    }

    #[test]
    fn test_valid_default_config_passes_validation() {
        let config = valid_config();
        assert!(validate(&config).is_ok());
    }

    #[test]
    fn test_port_zero_rejected() {
        let mut config = valid_config();
        config.server.port = 0;

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("server.port"));
    }

    #[test]
    fn test_pool_min_exceeds_max_rejected() {
        let mut config = valid_config();
        config.database.pool_min = 20;
        config.database.pool_max = 5;

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("pool_min"));
    }

    #[test]
    fn test_tls_cert_without_key_rejected() {
        let mut config = valid_config();
        config.server.tls_cert_path = Some("/path/to/cert.pem".into());
        config.server.tls_key_path = None;

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("tls_key_path"));
    }

    #[test]
    fn test_tls_key_without_cert_rejected() {
        let mut config = valid_config();
        config.server.tls_cert_path = None;
        config.server.tls_key_path = Some("/path/to/key.pem".into());

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("tls_cert_path"));
    }

    #[test]
    fn test_production_debug_rejected() {
        let mut config = valid_config();
        config.app.environment = Environment::Production;
        config.app.debug = true;
        // TLS must also be set for production
        config.server.tls_cert_path = Some("/cert".into());
        config.server.tls_key_path = Some("/key".into());

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("debug"));
    }

    #[test]
    fn test_production_without_tls_rejected() {
        let mut config = valid_config();
        config.app.environment = Environment::Production;
        config.app.debug = false;

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("TLS"));
    }

    #[test]
    fn test_multiple_errors_aggregated() {
        let mut config = valid_config();
        config.server.port = 0;
        config.server.max_connections = 0;
        config.server.worker_threads = 0;

        let err = validate(&config).unwrap_err();
        match err {
            ConfigError::MultipleValidation(ref errs) => {
                assert!(errs.len() >= 3, "Expected ≥3 errors, got {}", errs.len());
            }
            _ => panic!("Expected MultipleValidation, got: {err}"),
        }
    }

    #[test]
    fn test_empty_db_url_rejected() {
        let mut config = valid_config();
        config.database.url = String::new();

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("database.url"));
    }

    #[test]
    fn test_empty_host_rejected() {
        let mut config = valid_config();
        config.server.host = String::new();

        let err = validate(&config).unwrap_err();
        assert!(err.to_string().contains("server.host"));
    }
}
