## `src/env_override.rs` — Environment Variable Overrides

```rust
use crate::config::{Config, Environment, LogFormat, LogLevel};
use crate::error::{ConfigError, Result};
use std::env;

/// Prefix applied to all environment variable names.
const ENV_PREFIX: &str = "APP";

/// Applies environment variable overrides on top of a parsed configuration.
/// Convention: `APP_SECTION__FIELD` (double-underscore separates nesting).
pub fn apply_env_overrides(config: &mut Config) -> Result<()> {
    // --- App ---
    if let Some(v) = get_env("APP__NAME")? {
        config.app.name = v;
    }
    if let Some(v) = get_env("APP__ENVIRONMENT")? {
        config.app.environment = parse_environment(&v)?;
    }
    if let Some(v) = get_env("APP__DEBUG")? {
        config.app.debug = parse_bool("APP__DEBUG", &v)?;
    }
    if let Some(v) = get_env("APP__MAX_RETRIES")? {
        config.app.max_retries = parse_u32("APP__MAX_RETRIES", &v)?;
    }
    if let Some(v) = get_env("APP__REQUEST_TIMEOUT_SECS")? {
        config.app.request_timeout_secs = parse_u64("APP__REQUEST_TIMEOUT_SECS", &v)?;
    }

    // --- Server ---
    if let Some(v) = get_env("SERVER__HOST")? {
        config.server.host = v;
    }
    if let Some(v) = get_env("SERVER__PORT")? {
        config.server.port = parse_u16("SERVER__PORT", &v)?;
    }
    if let Some(v) = get_env("SERVER__MAX_CONNECTIONS")? {
        config.server.max_connections = parse_u32("SERVER__MAX_CONNECTIONS", &v)?;
    }
    if let Some(v) = get_env("SERVER__WORKER_THREADS")? {
        config.server.worker_threads = parse_usize("SERVER__WORKER_THREADS", &v)?;
    }
    if let Some(v) = get_env("SERVER__TLS_CERT_PATH")? {
        config.server.tls_cert_path = Some(v);
    }
    if let Some(v) = get_env("SERVER__TLS_KEY_PATH")? {
        config.server.tls_key_path = Some(v);
    }

    // --- Database ---
    if let Some(v) = get_env("DATABASE__URL")? {
        config.database.url = v;
    }
    if let Some(v) = get_env("DATABASE__POOL_MIN")? {
        config.database.pool_min = parse_u32("DATABASE__POOL_MIN", &v)?;
    }
    if let Some(v) = get_env("DATABASE__POOL_MAX")? {
        config.database.pool_max = parse_u32("DATABASE__POOL_MAX", &v)?;
    }
    if let Some(v) = get_env("DATABASE__CONNECTION_TIMEOUT_SECS")? {
        config.database.connection_timeout_secs =
            parse_u64("DATABASE__CONNECTION_TIMEOUT_SECS", &v)?;
    }
    if let Some(v) = get_env("DATABASE__RUN_MIGRATIONS")? {
        config.database.run_migrations = parse_bool("DATABASE__RUN_MIGRATIONS", &v)?;
    }

    // --- Logging ---
    if let Some(v) = get_env("LOGGING__LEVEL")? {
        config.logging.level = parse_log_level(&v)?;
    }
    if let Some(v) = get_env("LOGGING__FORMAT")? {
        config.logging.format = parse_log_format(&v)?;
    }
    if let Some(v) = get_env("LOGGING__FILE_PATH")? {
        config.logging.file_path = Some(v);
    }

    Ok(())
}

/// Reads `{ENV_PREFIX}_{suffix}` from the environment.
fn get_env(suffix: &str) -> Result<Option<String>> {
    let key = format!("{ENV_PREFIX}_{suffix}");
    match env::var(&key) {
        Ok(val) if !val.is_empty() => Ok(Some(val)),
        Ok(_) => Ok(None), // empty string treated as absent
        Err(env::VarError::NotPresent) => Ok(None),
        Err(env::VarError::NotUnicode(_)) => Err(ConfigError::EnvVarParse {
            key,
            value: "<non-utf8>".into(),
            reason: "value is not valid UTF-8".into(),
        }),
    }
}

// --- Parsing helpers returning domain-specific errors ---

fn parse_bool(key: &str, val: &str) -> Result<bool> {
    match val.to_lowercase().as_str() {
        "true" | "1" | "yes" => Ok(true),
        "false" | "0" | "no" => Ok(false),
        _ => Err(ConfigError::EnvVarParse {
            key: format!("{ENV_PREFIX}_{key}"),
            value: val.into(),
            reason: "expected true/false/1/0/yes/no".into(),
        }),
    }
}

fn parse_u16(key: &str, val: &str) -> Result<u16> {
    val.parse().map_err(|_| ConfigError::EnvVarParse {
        key: format!("{ENV_PREFIX}_{key}"),
        value: val.into(),
        reason: "expected u16".into(),
    })
}

fn parse_u32(key: &str, val: &str) -> Result<u32> {
    val.parse().map_err(|_| ConfigError::EnvVarParse {
        key: format!("{ENV_PREFIX}_{key}"),
        value: val.into(),
        reason: "expected u32".into(),
    })
}

fn parse_u64(key: &str, val: &str) -> Result<u64> {
    val.parse().map_err(|_| ConfigError::EnvVarParse {
        key: format!("{ENV_PREFIX}_{key}"),
        value: val.into(),
        reason: "expected u64".into(),
    })
}

fn parse_usize(key: &str, val: &str) -> Result<usize> {
    val.parse().map_err(|_| ConfigError::EnvVarParse {
        key: format!("{ENV_PREFIX}_{key}"),
        value: val.into(),
        reason: "expected usize".into(),
    })
}

fn parse_environment(val: &str) -> Result<Environment> {
    match val.to_lowercase().as_str() {
        "development" | "dev" => Ok(Environment::Development),
        "staging" => Ok(Environment::Staging),
        "production" | "prod" => Ok(Environment::Production),
        _ => Err(ConfigError::EnvVarParse {
            key: format!("{ENV_PREFIX}_APP__ENVIRONMENT"),
            value: val.into(),
            reason: "expected development/staging/production".into(),
        }),
    }
}

fn parse_log_level(val: &str) -> Result<LogLevel> {
    match val.to_lowercase().as_str() {
        "trace" => Ok(LogLevel::Trace),
        "debug" => Ok(LogLevel::Debug),
        "info" => Ok(LogLevel::Info),
        "warn" => Ok(LogLevel::Warn),
        "error" => Ok(LogLevel::Error),
        _ => Err(ConfigError::EnvVarParse {
            key: format!("{ENV_PREFIX}_LOGGING__LEVEL"),
            value: val.into(),
            reason: "expected trace/debug/info/warn/error".into(),
        }),
    }
}

fn parse_log_format(val: &str) -> Result<LogFormat> {
    match val.to_lowercase().as_str() {
        "text" => Ok(LogFormat::Text),
        "json" => Ok(LogFormat::Json),
        _ => Err(ConfigError::EnvVarParse {
            key: format!("{ENV_PREFIX}_LOGGING__FORMAT"),
            value: val.into(),
            reason: "expected text/json".into(),
        }),
    }
}

