mod tests {
    use super::*;
    use std::sync::Mutex;

    // Environment variables are process-global state.  
    // This mutex serializes tests that mutate env vars.
    static ENV_LOCK: Mutex<()> = Mutex::new(());

    /// RAII guard that restores env vars on drop.
    struct EnvGuard {
        vars: Vec<(String, Option<String>)>,
    }

    impl EnvGuard {
        fn new() -> Self {
            Self { vars: Vec::new() }
        }

        fn set(&mut self, key: &str, value: &str) {
            let prev = env::var(key).ok();
            self.vars.push((key.to_string(), prev));
            env::set_var(key, value);
        }
    }

    impl Drop for EnvGuard {
        fn drop(&mut self) {
            for (key, prev) in &self.vars {
                match prev {
                    Some(v) => env::set_var(key, v),
                    None => unsafe { env::remove_var(key) },
                }
            }
        }
    }

    #[test]
    fn test_env_override_server_port() {
        let _lock = ENV_LOCK.lock().unwrap();
        let mut guard = EnvGuard::new();
        guard.set("APP_SERVER__PORT", "9090");

        let mut config = Config::default();
        apply_env_overrides(&mut config).unwrap();
        assert_eq!(config.server.port, 9090);
    }

