```rust
use std::path::Path;

use crate::config::Config;
use crate::env_override::apply_env_overrides;
use crate::error::{ConfigError, Result};
use crate::validator::validate;

/// Supported configuration file formats.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Format {
    Toml,
    Json,
}

impl Format {
    /// Detects format from file extension.
    pub fn from_path(path: &Path) -> Result<Self> {
        match path.extension().and_then(|e| e.to_str()) {
            Some("toml") => Ok(Self::Toml),
            Some("json") => Ok(Self::Json),
            Some(ext) => Err(ConfigError::UnsupportedFormat(ext.to_string())),
            None => Err(ConfigError::UnsupportedFormat("<no extension>".to_string())),
        }
    }
}

/// Parses raw bytes into a `Config` using the specified format.
pub fn parse_config(data: &str, format: Format) -> Result<Config> {
    match format {
        Format::Toml => Ok(toml::from_str(data)?),
        Format::Json => Ok(serde_json::from_str(data)?),
    }
}

/// Builder that configures the loading pipeline before producing a `Config`.
#[derive(Debug)]
pub struct ConfigLoader {
    file_path: Option<Box<Path>>,
    apply_env: bool,
    skip_validation: bool,
}

impl ConfigLoader {
    /// Start building a configuration loader.
    pub fn new() -> Self {
        Self {
            file_path: None,
            apply_env: true,
            skip_validation: false,
        }
    }

    /// Load base configuration from a file (format auto-detected).
    pub fn file(mut self, path: impl AsRef<Path>) -> Self {
        self.file_path = Some(path.as_ref().into());
        self
    }

    /// Whether to apply `APP_*` environment variable overrides (default: true).
    pub fn with_env_overrides(mut self, enabled: bool) -> Self {
        self.apply_env = enabled;
        self
    }

    /// Skip validation — only useful in tests.
    #[cfg(any(test, feature = "test-utils"))]
    pub fn skip_validation(mut self) -> Self {
        self.skip_validation = true;
        self
    }

    /// Execute the loading pipeline: file → env overrides → validation.
    pub fn load(self) -> Result<Config> {
        tracing::info!("Loading configuration");

        // 1. Parse file or start from defaults
        let mut config = match &self.file_path {
            Some(path) => {
                tracing::info!(path = %path.display(), "Reading config file");
                let format = Format::from_path(path)?;
                let data = std::fs::read_to_string(path).map_err(|e| {
                    ConfigError::FileRead {
                        path: path.to_path_buf(),
                        source: e,
                    }
                })?;
                parse_config(&data, format)?
            }
            None => {
                tracing::info!("No config file specified, using defaults");
                Config::default()
            }
        };

        // 2. Overlay environment variables
        if self.apply_env {
            tracing::debug!("Applying environment variable overrides");
            apply_env_overrides(&mut config)?;
        }

        // 3. Validate
        if !self.skip_validation {
            tracing::debug!("Validating configuration");
            validate(&config)?;
        }

        tracing::info!(
            app = %config.app.name,
            env = %config.app.environment,
            "Configuration loaded successfully"
        );

        Ok(config)
    }
}

impl Default for ConfigLoader {
    fn default() -> Self {
        Self::new()
    }
}

