# Incremental Backup Config Parser in JavaScript

This example implements a config parser that reads backup configuration files and manages incremental backup state tracking.

## Config File Format

```ini
# backup.conf - Example configuration file

[general]
backup_name = daily_project_backup
base_dir = /home/user/projects
destination = /mnt/backup/projects
compression = gzip
log_level = info

[schedule]
frequency = daily
time = 02:00
retention_days = 30
max_full_backups = 4

[incremental]
enabled = true
full_backup_interval = 7       # full backup every N incremental cycles
checksum_algorithm = sha256
track_permissions = true
track_timestamps = true

[include]
paths[] = src/
paths[] = docs/
paths[] = config/
paths[] = package.json

[exclude]
patterns[] = node_modules/
patterns[] = .git/
patterns[] = *.log
patterns[] = *.tmp
patterns[] = .DS_Store
```

## Implementation

```javascript
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync, statSync, readdirSync } from "node:fs";
import { join, resolve, relative, extname } from "node:path";
import { EventEmitter } from "node:events";

// ──────────────────────────────────────────────
// Config Parser
// ──────────────────────────────────────────────

class BackupConfigParser {
  #rawText;
  #sections;
  #errors;

  constructor() {
    this.#sections = new Map();
    this.#errors = [];
  }

  /**
   * Parse a .conf / .ini style config file
   * Supports: sections, key=value, arrays (key[]), comments (#, ;)
   */
  parse(filePath) {
    if (!existsSync(filePath)) {
      throw new ConfigError(`Config file not found: ${filePath}`);
    }

    this.#rawText = readFileSync(filePath, "utf-8");
    let currentSection = "global";
    this.#sections.set(currentSection, {});

    const lines = this.#rawText.split(/\r?\n/);

    for (let i = 0; i < lines.length; i++) {
      const lineNum = i + 1;
      const raw = lines[i];
      const line = raw.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith("#") || line.startsWith(";")) {
        continue;
      }

      // Section header: [section_name]
      const sectionMatch = line.match(/^\[([a-zA-Z_][\w]*)\]$/);
      if (sectionMatch) {
        currentSection = sectionMatch[1].toLowerCase();
        if (!this.#sections.has(currentSection)) {
          this.#sections.set(currentSection, {});
        }
        continue;
      }

      // Key-value pair: key = value  OR  key[] = value (array append)
      const kvMatch = line.match(/^([a-zA-Z_][\w]*?)(\[\])?\s*=\s*(.*)$/);
      if (kvMatch) {
        const [, key, isArray, rawValue] = kvMatch;
        const value = this.#parseValue(rawValue);
        const section = this.#sections.get(currentSection);

        if (isArray) {
          if (!Array.isArray(section[key])) {
            section[key] = [];
          }
          section[key].push(value);
        } else {
          section[key] = value;
        }
        continue;
      }

      // Unrecognized line
      this.#errors.push({ line: lineNum, content: raw, message: "Unrecognized syntax" });
    }

    return this;
  }

  /** Coerce value strings into appropriate JS types */
  #parseValue(raw) {
    // Strip inline comments: value # comment
    const stripped = raw.replace(/\s+[#;].*$/, "").trim();

    if (stripped === "") return "";
    if (stripped === "true") return true;
    if (stripped === "false") return false;
    if (stripped === "null") return null;
    if (/^-?\d+$/.test(stripped)) return parseInt(stripped, 10);
    if (/^-?\d+\.\d+$/.test(stripped)) return parseFloat(stripped);

    // Remove surrounding quotes
    if (
      (stripped.startsWith('"') && stripped.endsWith('"')) ||
      (stripped.startsWith("'") && stripped.endsWith("'"))
    ) {
      return stripped.slice(1, -1);
    }

    return stripped;
  }

  /** Get a full section as an object */
  getSection(name) {
    return this.#sections.get(name.toLowerCase()) ?? null;
  }

  /** Get a single value with dot notation: "general.backup_name" */
  get(path, defaultValue = undefined) {
    const [section, key] = path.split(".");
    const sec = this.#sections.get(section?.toLowerCase());
    if (!sec || !(key in sec)) return defaultValue;
    return sec[key];
  }

  /** Validate config against a schema of required fields */
  validate(schema) {
    const errors = [];

    for (const rule of schema) {
      const value = this.get(rule.path);

      if (rule.required && (value === undefined || value === null)) {
        errors.push(`Missing required field: ${rule.path}`);
        continue;
      }

      if (value !== undefined && rule.type) {
        const actualType = Array.isArray(value) ? "array" : typeof value;
        if (actualType !== rule.type) {
          errors.push(`${rule.path}: expected ${rule.type}, got ${actualType}`);
        }
      }

      if (value !== undefined && rule.oneOf && !rule.oneOf.includes(value)) {
        errors.push(`${rule.path}: must be one of [${rule.oneOf}], got "${value}"`);
      }

      if (value !== undefined && rule.min !== undefined && value < rule.min) {
        errors.push(`${rule.path}: must be >= ${rule.min}, got ${value}`);
      }
    }

    if (errors.length > 0) {
      throw new ConfigValidationError(errors);
    }

    return true;
  }

  get parseErrors() {
    return [...this.#errors];
  }

  /** Build a typed BackupConfig object from parsed data */
  toBackupConfig() {
    return new BackupConfig(this);
  }
}

// ──────────────────────────────────────────────
// Typed Backup Configuration
// ──────────────────────────────────────────────

class BackupConfig {
  constructor(parser) {
    // Validate before building
    parser.validate(BackupConfig.SCHEMA);

    // General
    this.name = parser.get("general.backup_name", "unnamed_backup");
    this.baseDir = resolve(parser.get("general.base_dir", "."));
    this.destination = resolve(parser.get("general.destination"));
    this.compression = parser.get("general.compression", "none");
    this.logLevel = parser.get("general.log_level", "info");

    // Schedule
    this.frequency = parser.get("schedule.frequency", "daily");
    this.time = parser.get("schedule.time", "00:00");
    this.retentionDays = parser.get("schedule.retention_days", 30);
    this.maxFullBackups = parser.get("schedule.max_full_backups", 5);

    // Incremental settings
    this.incrementalEnabled = parser.get("incremental.enabled", true);
    this.fullBackupInterval = parser.get("incremental.full_backup_interval", 7);
    this.checksumAlgorithm = parser.get("incremental.checksum_algorithm", "sha256");
    this.trackPermissions = parser.get("incremental.track_permissions", true);
    this.trackTimestamps = parser.get("incremental.track_timestamps", true);

    // Include / Exclude
    this.includePaths = parser.get("include.paths", []);
    this.excludePatterns = parser.get("exclude.patterns", []);
  }

  static SCHEMA = [
    { path: "general.destination", required: true, type: "string" },
    { path: "general.compression", type: "string", oneOf: ["none", "gzip", "bzip2", "zstd"] },
    { path: "general.log_level", type: "string", oneOf: ["debug", "info", "warn", "error"] },
    { path: "schedule.retention_days", type: "number", min: 1 },
    { path: "incremental.full_backup_interval", type: "number", min: 1 },
    { path: "incremental.checksum_algorithm", type: "string", oneOf: ["md5", "sha1", "sha256"] },
  ];
}

// ──────────────────────────────────────────────
// File Manifest & Snapshot Tracking
// ──────────────────────────────────────────────

/** Represents metadata for a single tracked file */
class FileEntry {
  constructor(relativePath, stats, checksum) {
    this.path = relativePath;
    this.size = stats.size;
    this.mtime = stats.mtimeMs;
    this.mode = stats.mode;
    this.checksum = checksum;
  }

  /** Detect what changed compared to a previous entry */
  diffFrom(previous) {
    if (!previous) return "added";
    if (this.checksum !== previous.checksum) return "modified";
    if (this.size !== previous.size) return "modified";
    if (this.mode !== previous.mode) return "permissions";
    if (this.mtime !== previous.mtime) return "touched";
    return "unchanged";
  }

  toJSON() {
    return {
      path: this.path,
      size: this.size,
      mtime: this.mtime,
      mode: this.mode,
      checksum: this.checksum,
    };
  }
}

/** A snapshot = full manifest of all files at a point in time */
class Snapshot {
  constructor(data = {}) {
    this.id = data.id ?? Snapshot.generateId();
    this.timestamp = data.timestamp ?? Date.now();
    this.type = data.type ?? "incremental"; // "full" | "incremental"
    this.parentId = data.parentId ?? null;
    this.entries = new Map(); // relativePath → FileEntry

    // Restore entries from serialized data
    if (data.entries) {
      for (const e of data.entries) {
        this.entries.set(e.path, Object.assign(new FileEntry("", { size: 0, mtimeMs: 0, mode: 0 }, ""), e));
      }
    }
  }

  static generateId() {
    const now = new Date();
    const ts = now.toISOString().replace(/[-:T]/g, "").slice(0, 14);
    const rand = Math.random().toString(36).slice(2, 8);
    return `snap_${ts}_${rand}`;
  }

  addEntry(entry) {
    this.entries.set(entry.path, entry);
  }

  getEntry(relativePath) {
    return this.entries.get(relativePath) ?? null;
  }

  toJSON() {
    return {
      id: this.id,
      timestamp: this.timestamp,
      type: this.type,
      parentId: this.parentId,
      entries: Array.from(this.entries.values()).map((e) => e.toJSON()),
    };
  }
}

// ──────────────────────────────────────────────
// Incremental Backup Engine
// ──────────────────────────────────────────────

class IncrementalBackupEngine extends EventEmitter {
  #config;
  #stateFilePath;
  #state;

  constructor(config) {
    super();
    this.#config = config;
    this.#stateFilePath = join(config.destination, ".backup-state.json");
    this.#state = this.#loadState();
  }

  /** Load persisted backup state (snapshot history) */
  #loadState() {
    if (existsSync(this.#stateFilePath)) {
      try {
        const raw = JSON.parse(readFileSync(this.#stateFilePath, "utf-8"));
        return {
          snapshots: (raw.snapshots ?? []).map((s) => new Snapshot(s)),
          incrementalCount: raw.incrementalCount ?? 0,
        };
      } catch (err) {
        this.emit("warn", `Corrupted state file, starting fresh: ${err.message}`);
      }
    }
    return { snapshots: [], incrementalCount: 0 };
  }

  /** Persist backup state to disk */
  #saveState() {
    const data = {
      snapshots: this.#state.snapshots.map((s) => s.toJSON()),
      incrementalCount: this.#state.incrementalCount,
    };
    writeFileSync(this.#stateFilePath, JSON.stringify(data, null, 2), "utf-8");
  }

  /** Compute SHA-256 (or configured algo) checksum for a file */
  #checksumFile(filePath) {
    const content = readFileSync(filePath);
    return createHash(this.#config.checksumAlgorithm).update(content).digest("hex");
  }

  /** Check whether a path matches any exclusion pattern */
  #isExcluded(relativePath) {
    return this.#config.excludePatterns.some((pattern) => {
      // Simple glob: *.ext
      if (pattern.startsWith("*")) {
        return relativePath.endsWith(pattern.slice(1));
      }
      // Directory match: dir/
      if (pattern.endsWith("/")) {
        return relativePath.startsWith(pattern) || relativePath.includes(`/${pattern}`);
      }
      // Exact filename match
      return relativePath === pattern || relativePath.endsWith(`/${pattern}`);
    });
  }

  /** Recursively scan a directory and build FileEntry list */
  #scanDirectory(dirPath, basePath = dirPath) {
    const entries = [];

    if (!existsSync(dirPath)) return entries;

    const items = readdirSync(dirPath, { withFileTypes: true });

    for (const item of items) {
      const fullPath = join(dirPath, item.name);
      const relPath = relative(basePath, fullPath);

      if (this.#isExcluded(relPath)) {
        this.emit("skip", relPath);
        continue;
      }

      if (item.isDirectory()) {
        entries.push(...this.#scanDirectory(fullPath, basePath));
      } else if (item.isFile()) {
        const stats = statSync(fullPath);
        const checksum = this.#checksumFile(fullPath);
        entries.push(new FileEntry(relPath, stats, checksum));
      }
    }

    return entries;
  }

  /** Determine if this run should be a full or incremental backup */
  shouldDoFullBackup() {
    if (!this.#config.incrementalEnabled) return true;
    if (this.#state.snapshots.length === 0) return true;
    if (this.#state.incrementalCount >= this.#config.fullBackupInterval) return true;
    return false;
  }

  /** Get the most recent snapshot */
  get lastSnapshot() {
    return this.#state.snapshots.at(-1) ?? null;
  }

  /** Main backup execution — returns a diff report */
  run() {
    const isFullBackup = this.shouldDoFullBackup();
    const backupType = isFullBackup ? "full" : "incremental";

    this.emit("start", { type: backupType, config: this.#config.name });

    // 1. Scan current file system
    const scanPaths =
      this.#config.includePaths.length > 0
        ? this.#config.includePaths.map((p) => join(this.#config.baseDir, p))
        : [this.#config.baseDir];

    const currentEntries = [];
    for (const scanPath of scanPaths) {
      currentEntries.push(...this.#scanDirectory(scanPath, this.#config.baseDir));
    }

    this.emit("scanned", { fileCount: currentEntries.length });

    // 2. Build new snapshot
    const snapshot = new Snapshot({
      type: backupType,
      parentId: this.lastSnapshot?.id ?? null,
    });

    for (const entry of currentEntries) {
      snapshot.addEntry(entry);
    }

    // 3. Compute diff against last snapshot
    const diff = this.#computeDiff(snapshot, isFullBackup ? null : this.lastSnapshot);

    // 4. Update state
    this.#state.snapshots.push(snapshot);
    this.#state.incrementalCount = isFullBackup ? 0 : this.#state.incrementalCount + 1;

    // 5. Enforce retention: remove old snapshots
    this.#enforceRetention();

    // 6. Persist
    this.#saveState();

    this.emit("complete", {
      snapshotId: snapshot.id,
      type: backupType,
      summary: diff.summary,
    });

    return diff;
  }

  /** Compare two snapshots and produce a change report */
  #computeDiff(current, previous) {
    const changes = {
      added: [],
      modified: [],
      deleted: [],
      unchanged: [],
      permissions: [],
    };

    // Check current entries against previous
    for (const [path, entry] of current.entries) {
      const prevEntry = previous?.getEntry(path) ?? null;
      const status = entry.diffFrom(prevEntry);

      switch (status) {
        case "added":
          changes.added.push(entry);
          break;
        case "modified":
          changes.modified.push({ current: entry, previous: prevEntry });
          break;
        case "permissions":
          changes.permissions.push({ current: entry, previous: prevEntry });
          break;
        case "unchanged":
        case "touched":
          changes.unchanged.push(entry);
          break;
      }
    }

    // Check for deleted files (in previous but not current)
    if (previous) {
      for (const [path] of previous.entries) {
        if (!current.entries.has(path)) {
          changes.deleted.push(previous.getEntry(path));
        }
      }
    }

    const totalChanged = changes.added.length + changes.modified.length + changes.deleted.length;

    return {
      changes,
      summary: {
        added: changes.added.length,
        modified: changes.modified.length,
        deleted: changes.deleted.length,
        unchanged: changes.unchanged.length,
        permissions: changes.permissions.length,
        totalFiles: current.entries.size,
        totalChanged,
        backupNeeded: totalChanged > 0,
      },
    };
  }

  /** Remove snapshots older than retention window */
  #enforceRetention() {
    const cutoff = Date.now() - this.#config.retentionDays * 86_400_000;

    // Always keep at least 1 full backup
    const fullBackups = this.#state.snapshots.filter((s) => s.type === "full");

    this.#state.snapshots = this.#state.snapshots.filter((snapshot) => {
      if (snapshot.timestamp >= cutoff) return true;
      // Keep if it's the only full backup
      if (snapshot.type === "full" && fullBackups.length <= 1) return true;
      this.emit("pruned", snapshot.id);
      return false;
    });

    // Enforce max full backups
    while (fullBackups.length > this.#config.maxFullBackups) {
      const oldest = fullBackups.shift();
      this.#state.snapshots = this.#state.snapshots.filter((s) => s.id !== oldest.id);
      this.emit("pruned", oldest.id);
    }
  }

  /** Get a summary of backup history */
  getHistory() {
    return this.#state.snapshots.map((s) => ({
      id: s.id,
      type: s.type,
      timestamp: new Date(s.timestamp).toISOString(),
      fileCount: s.entries.size,
      parentId: s.parentId,
    }));
  }
}

