class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = "ConfigError";
  }
}

class ConfigValidationError extends Error {
  constructor(errors) {
    super(`Config validation failed:\n  - ${errors.join("\n  - ")}`);
    this.name = "ConfigValidationError";
    this.errors = errors;
  }
}

// ──────────────────────────────────────────────
// Pretty Printer for Reports
// ──────────────────────────────────────────────

function formatDiffReport(diff) {
  const { summary, changes } = diff;
  const lines = [
    "╔══════════════════════════════════════════╗",
    "║        INCREMENTAL BACKUP REPORT         ║",
    "╠══════════════════════════════════════════╣",
    `║  Total files scanned:  ${String(summary.totalFiles).padStart(15)} ║`,
    `║  Added:                ${String(summary.added).padStart(15)} ║`,
    `║  Modified:             ${String(summary.modified).padStart(15)} ║`,
    `║  Deleted:              ${String(summary.deleted).padStart(15)} ║`,
    `║  Permission changes:   ${String(summary.permissions).padStart(15)} ║`,
    `║  Unchanged:            ${String(summary.unchanged).padStart(15)} ║`,
    "╠══════════════════════════════════════════╣",
    `║  Backup needed:  ${summary.backupNeeded ? "    ✅ YES" : "    ⛔ NO "}             ║`,
    "╚══════════════════════════════════════════╝",
  ];

  if (changes.added.length > 0) {
    lines.push("\n  ➕ Added:");
    changes.added.slice(0, 10).forEach((e) => lines.push(`     ${e.path}`));
    if (changes.added.length > 10) lines.push(`     ... and ${changes.added.length - 10} more`);
  }

  if (changes.modified.length > 0) {
    lines.push("\n  ✏️  Modified:");
    changes.modified.slice(0, 10).forEach(({ current, previous }) => {
      const sizeDelta = current.size - previous.size;
      const sign = sizeDelta >= 0 ? "+" : "";
      lines.push(`     ${current.path} (${sign}${sizeDelta} bytes)`);
    });
  }

  if (changes.deleted.length > 0) {
    lines.push("\n  🗑️  Deleted:");
    changes.deleted.slice(0, 10).forEach((e) => lines.push(`     ${e.path}`));
  }

  return lines.join("\n");
}

