use crate::error::{BackupError, Result};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::fs;

// ── Top-level config ──────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackupConfig {
    pub general: GeneralConfig,
    pub schedule: ScheduleConfig,
    pub retention: RetentionConfig,
    pub sources: Vec<SourceConfig>,
    #[serde(default)]
    pub compression: CompressionConfig,
    #[serde(default)]
    pub encryption: EncryptionConfig,
}

// ── Section structs ───────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GeneralConfig {
    pub backup_name: String,
    pub destination: PathBuf,
    #[serde(default = "default_manifest_path")]
    pub manifest_path: PathBuf,
    #[serde(default)]
    pub verbose: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScheduleConfig {
    #[serde(default = "default_true")]
    pub enabled: bool,
    #[serde(default = "default_interval")]
    pub interval_hours: u32,
    #[serde(default = "default_retries")]
    pub max_retries: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RetentionConfig {
    #[serde(default = "default_max_full")]
    pub max_full_backups: u32,
    #[serde(default = "default_max_incremental")]
    pub max_incremental_per_full: u32,
    #[serde(default = "default_max_age")]
    pub max_age_days: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SourceConfig {
    pub path: PathBuf,
    #[serde(default = "default_true")]
    pub recursive: bool,
    #[serde(default)]
    pub include_patterns: Vec<String>,
    #[serde(default)]
    pub exclude_patterns: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CompressionConfig {
    #[serde(default)]
    pub enabled: bool,
    #[serde(default = "default_compression_algo")]
    pub algorithm: CompressionAlgorithm,
    #[serde(default = "default_compression_level")]
    pub level: u8,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EncryptionConfig {
    #[serde(default)]
    pub enabled: bool,
    #[serde(default = "default_encryption_algo")]
    pub algorithm: EncryptionAlgorithm,
    #[serde(default)]
    pub key_file: PathBuf,
}

// ── Enums for algorithms ──────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum CompressionAlgorithm {
    Gzip,
    Zstd,
    Lz4,
    None,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum EncryptionAlgorithm {
    #[serde(rename = "aes-256-gcm")]
    Aes256Gcm,
    #[serde(rename = "chacha20-poly1305")]
    ChaCha20Poly1305,
    None,
}

// ── Default value functions ───────────────────────────────────────

fn default_true() -> bool { true }
fn default_interval() -> u32 { 24 }
fn default_retries() -> u32 { 3 }
fn default_max_full() -> u32 { 5 }
fn default_max_incremental() -> u32 { 30 }
fn default_max_age() -> u32 { 90 }
fn default_compression_algo() -> CompressionAlgorithm { CompressionAlgorithm::Gzip }
fn default_compression_level() -> u8 { 6 }
fn default_encryption_algo() -> EncryptionAlgorithm { EncryptionAlgorithm::None }
fn default_manifest_path() -> PathBuf { PathBuf::from(".backup_manifest.json") }

impl Default for CompressionConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            algorithm: CompressionAlgorithm::Gzip,
            level: 6,
        }
    }
}

impl Default for EncryptionConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            algorithm: EncryptionAlgorithm::None,
            key_file: PathBuf::new(),
        }
    }
}

// ── Parsing + Validation ──────────────────────────────────────────

impl BackupConfig {
    /// Parse config from a TOML file path
    pub fn from_file(path: &Path) -> Result<Self> {
        if !path.exists() {
            return Err(BackupError::ConfigNotFound {
                path: path.to_path_buf(),
            });
        }

        let contents = fs::read_to_string(path)?;
        Self::from_str(&contents)
    }

    /// Parse config from a TOML string
    pub fn from_str(toml_str: &str) -> Result<Self> {
        let config: BackupConfig = toml::from_str(toml_str).map_err(|e| {
            BackupError::ConfigParse {
                reason: e.to_string(),
            }
        })?;

        config.validate()?;
        Ok(config)
    }

    /// Validate all fields after parsing
    fn validate(&self) -> Result<()> {
        // Backup name must not be empty
        if self.general.backup_name.trim().is_empty() {
            return Err(BackupError::ConfigValidation {
                field: "general.backup_name".into(),
                reason: "must not be empty".into(),
            });
        }

        // At least one source required
        if self.sources.is_empty() {
            return Err(BackupError::ConfigValidation {
                field: "sources".into(),
                reason: "at least one source path required".into(),
            });
        }

        // Validate each source path exists
        for (i, source) in self.sources.iter().enumerate() {
            if !source.path.exists() {
                return Err(BackupError::SourceNotFound {
                    path: source.path.clone(),
                });
            }

            // Validate glob patterns are syntactically correct
            for pattern in &source.include_patterns {
                Self::validate_glob(pattern, &format!("sources[{i}].include_patterns"))?;
            }
            for pattern in &source.exclude_patterns {
                Self::validate_glob(pattern, &format!("sources[{i}].exclude_patterns"))?;
            }
        }

        // Compression level range
        if self.compression.enabled && self.compression.level > 9 {
            return Err(BackupError::ConfigValidation {
                field: "compression.level".into(),
                reason: format!("must be 0-9, got {}", self.compression.level),
            });
        }

        // Encryption key file must exist if encryption enabled
        if self.encryption.enabled && !self.encryption.key_file.exists() {
            return Err(BackupError::ConfigValidation {
                field: "encryption.key_file".into(),
                reason: format!(
                    "key file not found: {}",
                    self.encryption.key_file.display()
                ),
            });
        }

        // Retention sanity checks
        if self.retention.max_full_backups == 0 {
            return Err(BackupError::ConfigValidation {
                field: "retention.max_full_backups".into(),
                reason: "must be at least 1".into(),
            });
        }

        Ok(())
    }

    /// Basic glob syntax check (ensure no unmatched brackets, etc.)
    fn validate_glob(pattern: &str, field: &str) -> Result<()> {
        // Simple validation: check balanced brackets
        let mut bracket_depth = 0i32;
        for ch in pattern.chars() {
            match ch {
                '[' => bracket_depth += 1,
                ']' => bracket_depth -= 1,
                _ => {}
            }
            if bracket_depth < 0 {
                return Err(BackupError::ConfigValidation {
                    field: field.into(),
                    reason: format!("invalid glob pattern: '{pattern}'"),
                });
            }
        }
        if bracket_depth != 0 {
            return Err(BackupError::ConfigValidation {
                field: field.into(),
                reason: format!("unbalanced brackets in pattern: '{pattern}'"),
            });
        }
        Ok(())
    }

    /// Pretty-print the loaded configuration
    pub fn summary(&self) -> String {
        let mut s = String::new();
        s.push_str(&format!("╔══ Backup Config: {} ══\n", self.general.backup_name));
        s.push_str(&format!("║ Destination : {}\n", self.general.destination.display()));
        s.push_str(&format!("║ Manifest    : {}\n", self.general.manifest_path.display()));
        s.push_str(&format!("║ Schedule    : every {}h (retries: {})\n",
            self.schedule.interval_hours, self.schedule.max_retries));
        s.push_str(&format!("║ Retention   : {} full, {} incremental, {}d max age\n",
            self.retention.max_full_backups,
            self.retention.max_incremental_per_full,
            self.retention.max_age_days));
        s.push_str(&format!("║ Compression : {:?} (level {})\n",
            self.compression.algorithm, self.compression.level));
        s.push_str("║ Sources:\n");
        for src in &self.sources {
            s.push_str(&format!("║   • {} (recursive: {})\n",
                src.path.display(), src.recursive));
            if !src.include_patterns.is_empty() {
                s.push_str(&format!("║     include: {:?}\n", src.include_patterns));
            }
            if !src.exclude_patterns.is_empty() {
                s.push_str(&format!("║     exclude: {:?}\n", src.exclude_patterns));
            }
        }
        s.push_str("╚═══════════════════════════════════");
        s
    }
}
