use crate::error::{BackupError, Result};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

/// Tracks the state of every file across backup runs.
/// Persisted as JSON between executions.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackupManifest {
    /// Unique name identifying this backup set
    pub backup_name: String,
    /// When the last full backup was taken
    pub last_full_backup: Option<DateTime<Utc>>,
    /// When the last incremental backup was taken
    pub last_incremental_backup: Option<DateTime<Utc>>,
    /// Total number of incremental runs since last full
    pub incremental_count: u32,
    /// Running counter for backup IDs
    pub next_backup_id: u64,
    /// Per-file state: path → metadata snapshot
    pub files: HashMap<PathBuf, FileRecord>,
}

/// Snapshot of a single file at its last backup time
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileRecord {
    /// SHA-256 hash of file contents
    pub hash: String,
    /// File size in bytes
    pub size: u64,
    /// Last modification time from the filesystem
    pub modified: DateTime<Utc>,
    /// Which backup run last captured this file
    pub last_backup_id: u64,
    /// Whether this file was deleted (tombstone)
    pub deleted: bool,
}

/// What changed since the last backup
#[derive(Debug, Default)]
pub struct ChangeSet {
    pub added: Vec<PathBuf>,
    pub modified: Vec<PathBuf>,
    pub deleted: Vec<PathBuf>,
}

impl ChangeSet {
    pub fn total_changes(&self) -> usize {
        self.added.len() + self.modified.len() + self.deleted.len()
    }

    pub fn is_empty(&self) -> bool {
        self.total_changes() == 0
    }

    pub fn summary(&self) -> String {
        format!(
            "+{} added, ~{} modified, -{} deleted",
            self.added.len(),
            self.modified.len(),
            self.deleted.len()
        )
    }
}

impl BackupManifest {
    /// Create a fresh manifest for a new backup set
    pub fn new(backup_name: &str) -> Self {
        Self {
            backup_name: backup_name.to_string(),
            last_full_backup: None,
            last_incremental_backup: None,
            incremental_count: 0,
            next_backup_id: 1,
            files: HashMap::new(),
        }
    }

    /// Load manifest from disk, or create new if missing
    pub fn load_or_create(path: &Path, backup_name: &str) -> Result<Self> {
        if path.exists() {
            let data = fs::read_to_string(path)?;
            let manifest: Self = serde_json::from_str(&data).map_err(|e| {
                BackupError::Manifest {
                    reason: format!("corrupt manifest: {e}"),
                }
            })?;

            // Verify it belongs to the same backup set
            if manifest.backup_name != backup_name {
                return Err(BackupError::Manifest {
                    reason: format!(
                        "manifest name mismatch: expected '{}', got '{}'",
                        backup_name, manifest.backup_name
                    ),
                });
            }

            Ok(manifest)
        } else {
            Ok(Self::new(backup_name))
        }
    }

    /// Persist the manifest to disk
    pub fn save(&self, path: &Path) -> Result<()> {
        // Ensure parent directory exists
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }

        let json = serde_json::to_string_pretty(self)?;
        fs::write(path, json)?;
        Ok(())
    }

    /// Compare current filesystem state against the manifest
    /// to determine what files need to be backed up
    pub fn detect_changes(
        &self,
        current_files: &HashMap<PathBuf, (String, u64, DateTime<Utc>)>,
    ) -> ChangeSet {
        let mut changes = ChangeSet::default();

        // Check for new and modified files
        for (path, (hash, _size, _modified)) in current_files {
            match self.files.get(path) {
                None => {
                    // File not in manifest → new file
                    changes.added.push(path.clone());
                }
                Some(record) if record.deleted => {
                    // Was deleted, now reappeared → treat as added
                    changes.added.push(path.clone());
                }
                Some(record) if record.hash != *hash => {
                    // Hash differs → modified
                    changes.modified.push(path.clone());
                }
                Some(_) => {
                    // Unchanged — skip
                }
            }
        }

        // Check for deleted files
        for (path, record) in &self.files {
            if !record.deleted && !current_files.contains_key(path) {
                changes.deleted.push(path.clone());
            }
        }

        // Sort for deterministic output
        changes.added.sort();
        changes.modified.sort();
        changes.deleted.sort();

        changes
    }

    /// Update the manifest after a successful backup
    pub fn apply_changes(
        &mut self,
        changes: &ChangeSet,
        current_files: &HashMap<PathBuf, (String, u64, DateTime<Utc>)>,
    ) {
        let backup_id = self.next_backup_id;
        self.next_backup_id += 1;
        self.incremental_count += 1;
        self.last_incremental_backup = Some(Utc::now());

        // Record added & modified files
        for path in changes.added.iter().chain(changes.modified.iter()) {
            if let Some((hash, size, modified)) = current_files.get(path) {
                self.files.insert(
                    path.clone(),
                    FileRecord {
                        hash: hash.clone(),
                        size: *size,
                        modified: *modified,
                        last_backup_id: backup_id,
                        deleted: false,
                    },
                );
            }
        }

        // Mark deleted files as tombstones
        for path in &changes.deleted {
            if let Some(record) = self.files.get_mut(path) {
                record.deleted = true;
                record.last_backup_id = backup_id;
            }
        }
    }

    /// Check if a full backup is needed (first run or too many incrementals)
    pub fn needs_full_backup(&self, max_incremental: u32) -> bool {
        self.last_full_backup.is_none() || self.incremental_count >= max_incremental
    }

    /// Reset the incremental counter (called after a full backup)
    pub fn mark_full_backup(&mut self) {
        self.last_full_backup = Some(Utc::now());
        self.incremental_count = 0;
    }
}
