```rust
use crate::config::{BackupConfig, SourceConfig};
use crate::error::{BackupError, Result};
use crate::manifest::{BackupManifest, ChangeSet};
use chrono::{DateTime, Utc};
use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::UNIX_EPOCH;

/// The main backup engine that ties config, manifest, and I/O together
pub struct BackupEngine {
    config: BackupConfig,
    manifest: BackupManifest,
}

impl BackupEngine {
    /// Initialize the engine from a parsed config
    pub fn new(config: BackupConfig) -> Result<Self> {
        let manifest = BackupManifest::load_or_create(
            &config.general.manifest_path,
            &config.general.backup_name,
        )?;

        Ok(Self { config, manifest })
    }

    /// Run the backup process
    pub fn run(&mut self) -> Result<BackupReport> {
        let verbose = self.config.general.verbose;

        if verbose {
            println!("{}", self.config.summary());
            println!();
        }

        // Step 1: Decide full vs incremental
        let is_full = self
            .manifest
            .needs_full_backup(self.config.retention.max_incremental_per_full);

        if verbose {
            let kind = if is_full { "FULL" } else { "INCREMENTAL" };
            println!("▶ Starting {kind} backup...");
        }

        // Step 2: Scan all source directories and hash files
        if verbose {
            println!("  Scanning source directories...");
        }
        let current_files = self.scan_sources()?;

        if verbose {
            println!("  Found {} files across all sources", current_files.len());
        }

        // Step 3: Detect changes against the manifest
        let changes = if is_full {
            // Full backup: treat every file as "added"
            ChangeSet {
                added: current_files.keys().cloned().collect(),
                modified: Vec::new(),
                deleted: Vec::new(),
            }
        } else {
            self.manifest.detect_changes(&current_files)
        };

        if verbose {
            println!("  Changes: {}", changes.summary());
        }

        if changes.is_empty() {
            if verbose {
                println!("  ✓ No changes detected — skipping backup");
            }
            return Ok(BackupReport {
                backup_type: BackupType::Incremental,
                files_added: 0,
                files_modified: 0,
                files_deleted: 0,
                bytes_transferred: 0,
                timestamp: Utc::now(),
                skipped: true,
            });
        }

        // Step 4: Create the backup directory
        let backup_dir = self.create_backup_dir(is_full)?;

        if verbose {
            println!("  Backup dir: {}", backup_dir.display());
        }

        // Step 5: Copy changed files to the backup directory
        let bytes_transferred = self.copy_files(&changes, &backup_dir, verbose)?;

        // Step 6: Write a deletion log for deleted files
        if !changes.deleted.is_empty() {
            self.write_deletion_log(&changes.deleted, &backup_dir)?;
        }

        // Step 7: Update and save the manifest
        if is_full {
            self.manifest.mark_full_backup();
        }
        self.manifest.apply_changes(&changes, &current_files);
        self.manifest.save(&self.config.general.manifest_path)?;

        if verbose {
            println!("  ✓ Manifest saved");
        }

        // Step 8: Enforce retention policy
        self.enforce_retention(verbose)?;

        let report = BackupReport {
            backup_type: if is_full {
                BackupType::Full
            } else {
                BackupType::Incremental
            },
            files_added: changes.added.len(),
            files_modified: changes.modified.len(),
            files_deleted: changes.deleted.len(),
            bytes_transferred,
            timestamp: Utc::now(),
            skipped: false,
        };

        if verbose {
            println!("\n{report}");
        }

        Ok(report)
    }

    /// Scan all configured sources, hash each file, collect metadata
    fn scan_sources(&self) -> Result<HashMap<PathBuf, (String, u64, DateTime<Utc>)>> {
        let mut files = HashMap::new();

        for source in &self.config.sources {
            self.scan_directory(&source.path, source, &mut files)?;
        }

        Ok(files)
    }

    /// Recursively walk a directory and collect matching files
    fn scan_directory(
        &self,
        dir: &Path,
        source: &SourceConfig,
        files: &mut HashMap<PathBuf, (String, u64, DateTime<Utc>)>,
    ) -> Result<()> {
        if !dir.is_dir() {
            return Ok(());
        }

        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            let path = entry.path();

            if path.is_dir() && source.recursive {
                // Check exclusion before recursing
                if !self.is_excluded(&path, &source.exclude_patterns) {
                    self.scan_directory(&path, source, files)?;
                }
            } else if path.is_file() {
                // Apply include/exclude filters
                if self.matches_filters(&path, &source.include_patterns, &source.exclude_patterns)
                {
                    let metadata = fs::metadata(&path)?;
                    let size = metadata.len();
                    let modified = metadata
                        .modified()
                        .unwrap_or(UNIX_EPOCH)
                        .duration_since(UNIX_EPOCH)
                        .unwrap_or_default();
                    let modified_dt = DateTime::<Utc>::from(UNIX_EPOCH + modified);
                    let hash = self.hash_file(&path)?;

                    files.insert(path, (hash, size, modified_dt));
                }
            }
        }

        Ok(())
    }

    /// Compute SHA-256 hash of a file
    fn hash_file(&self, path: &Path) -> Result<String> {
        let data = fs::read(path)?;
        let mut hasher = Sha256::new();
        hasher.update(&data);
        let result = hasher.finalize();
        Ok(hex::encode(result))
    }

    /// Check if a file matches include patterns and doesn't match excludes
    fn matches_filters(
        &self,
        path: &Path,
        includes: &[String],
        excludes: &[String],
    ) -> bool {
        let file_name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("");

        let path_str = path.to_string_lossy();

        // If excludes match, skip the file
        for pattern in excludes {
            if simple_glob_match(pattern, file_name)
                || simple_glob_match(pattern, &path_str)
            {
                return false;
            }
        }

        // If no includes specified, include everything
        if includes.is_empty() {
            return true;
        }

        // Otherwise, file must match at least one include pattern
        for pattern in includes {
            if simple_glob_match(pattern, file_name) {
                return true;
            }
        }

        false
    }

    /// Check if a directory path matches any exclusion pattern
    fn is_excluded(&self, path: &Path, excludes: &[String]) -> bool {
        let path_str = path.to_string_lossy();
        let dir_name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("");

        for pattern in excludes {
            if simple_glob_match(pattern, dir_name)
                || simple_glob_match(pattern, &path_str)
            {
                return true;
            }
        }
        false
    }

    /// Create a timestamped backup directory
    fn create_backup_dir(&self, is_full: bool) -> Result<PathBuf> {
        let timestamp = Utc::now().format("%Y%m%d_%H%M%S");
        let kind = if is_full { "full" } else { "incr" };
        let dir = self
            .config
            .general
            .destination
            .join(format!("{}_{kind}_{timestamp}", self.config.general.backup_name));

        fs::create_dir_all(&dir)?;
        Ok(dir)
    }

    /// Copy the changed files into the backup directory, preserving relative paths
    fn copy_files(
        &self,
        changes: &ChangeSet,
        backup_dir: &Path,
        verbose: bool,
    ) -> Result<u64> {
        let mut total_bytes: u64 = 0;

        let files_to_copy: Vec<&PathBuf> = changes
            .added
            .iter()
            .chain(changes.modified.iter())
            .collect();

        for (i, src_path) in files_to_copy.iter().enumerate() {
            // Build a relative destination path
            let relative = self.make_relative(src_path);
            let dest_path = backup_dir.join(&relative);

            // Create parent directories
            if let Some(parent) = dest_path.parent() {
                fs::create_dir_all(parent)?;
            }

            // Copy the file
            let bytes = fs::copy(src_path, &dest_path).map_err(|e| {
                BackupError::BackupFailed {
                    path: src_path.to_path_buf(),
                    reason: e.to_string(),
                }
            })?;

            total_bytes += bytes;

            if verbose {
                let pct = ((i + 1) as f64 / files_to_copy.len() as f64 * 100.0) as u8;
                println!(
                    "  [{pct:>3}%] {} ({} bytes)",
                    relative.display(),
                    bytes
                );
            }
        }

        Ok(total_bytes)
    }

    /// Make a path relative to the first matching source root
    fn make_relative(&self, path: &Path) -> PathBuf {
        for source in &self.config.sources {
            if let Ok(rel) = path.strip_prefix(&source.path) {
                // Prefix with the source dir name for clarity
                let source_name = source
                    .path
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("unknown");
                return PathBuf::from(source_name).join(rel);
            }
        }
        // Fallback: use the full path
        path.to_path_buf()
    }

    /// Write a log of deleted files in the backup directory
    fn write_deletion_log(&self, deleted: &[PathBuf], backup_dir: &Path) -> Result<()> {
        let log_path = backup_dir.join("_deleted_files.log");
        let contents: String = deleted
            .iter()
            .map(|p| p.to_string_lossy().to_string())
            .collect::<Vec<_>>()
            .join("\n");

        fs::write(log_path, contents)?;
        Ok(())
    }

    /// Remove old backups that exceed retention limits
    fn enforce_retention(&self, verbose: bool) -> Result<()> {
        let dest = &self.config.general.destination;
        let prefix = &self.config.general.backup_name;

        if !dest.exists() {
            return Ok(());
        }

        // Gather all backup directories for this backup set
        let mut full_backups: Vec<PathBuf> = Vec::new();
        let mut incr_backups: Vec<PathBuf> = Vec::new();

        for entry in fs::read_dir(dest)? {
            let entry = entry?;
            let name = entry.file_name().to_string_lossy().to_string();

            if name.starts_with(prefix) && entry.path().is_dir() {
                if name.contains("_full_") {
                    full_backups.push(entry.path());
                } else if name.contains("_incr_") {
                    incr_backups.push(entry.path());
                }
            }
        }

        // Sort by name (which includes timestamp) — oldest first
        full_backups.sort();
        incr_backups.sort();

        // Remove excess full backups
        let max_full = self.config.retention.max_full_backups as usize;
        while full_backups.len() > max_full {
            let old = full_backups.remove(0);
            if verbose {
                println!("  🗑 Removing old full backup: {}", old.display());
            }
            fs::remove_dir_all(&old)?;
        }

        // Remove excess incremental backups
        let max_incr = self.config.retention.max_incremental_per_full as usize;
        while incr_backups.len() > max_incr {
            let old = incr_backups.remove(0);
            if verbose {
                println!("  🗑 Removing old incremental: {}", old.display());
            }
            fs::remove_dir_all(&old)?;
        }

        Ok(())
    }
}

// ── Simple glob matcher ───────────────────────────────────────────

/// Minimal glob matching supporting `*` (any chars) and `?` (single char)
fn simple_glob_match(pattern: &str, text: &str) -> bool {
    let pattern: Vec<char> = pattern.chars().collect();
    let text: Vec<char> = text.chars().collect();
    glob_match_recursive(&pattern, &text, 0, 0)
}

fn glob_match_recursive(pattern: &[char], text: &[char], pi: usize, ti: usize) -> bool {
    if pi == pattern.len() && ti == text.len() {
        return true;
    }
    if pi == pattern.len() {
        return false;
    }

    match pattern[pi] {
        '*' => {
            // '*' can match zero or more characters
            for i in ti..=text.len() {
                if glob_match_recursive(pattern, text, pi + 1, i) {
                    return true;
                }
            }
            false
        }
        '?' => {
            // '?' matches exactly one character
            if ti < text.len() {
                glob_match_recursive(pattern, text, pi + 1, ti + 1)
            } else {
                false
            }
        }
        ch => {
            if ti < text.len() && text[ti] == ch {
                glob_match_recursive(pattern, text, pi + 1, ti + 1)
            } else {
                false
            }
        }
    }
}

// ── Report types ──────────────────────────────────────────────────

#[derive(Debug)]
pub enum BackupType {
    Full,
    Incremental,
}

#[derive(Debug)]
pub struct BackupReport {
    pub backup_type: BackupType,
    pub files_added: usize,
    pub files_modified: usize,
    pub files_deleted: usize,
    pub bytes_transferred: u64,
    pub timestamp: DateTime<Utc>,
    pub skipped: bool,
}

impl std::fmt::Display for BackupReport {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.skipped {
            return write!(f, "Backup skipped — no changes detected");
        }

        let kind = match self.backup_type {
            BackupType::Full => "FULL",
            BackupType::Incremental => "INCREMENTAL",
        };

        write!(
            f,
            "═══ Backup Report ═══\n\
             Type      : {kind}\n\
             Added     : {} files\n\
             Modified  : {} files\n\
             Deleted   : {} files\n\
             Transferred: {} bytes ({:.2} MB)\n\
             Timestamp : {}",
            self.files_added,
            self.files_modified,
            self.files_deleted,
            self.bytes_transferred,
            self.bytes_transferred as f64 / 1_048_576.0,
            self.timestamp.format("%Y-%m-%d %H:%M:%S UTC"),
        )
    }
}
