use config::BackupConfig;
use backup::BackupEngine;
use std::path::Path;
use std::process;

fn main() {
    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "backup_config.toml".to_string());

    println!("Loading config from: {config_path}\n");

    // Step 1: Parse configuration
    let config = match BackupConfig::from_file(Path::new(&config_path)) {
        Ok(cfg) => cfg,
        Err(e) => {
            eprintln!("❌ Configuration error: {e}");
            process::exit(1);
        }
    };

    // Step 2: Initialize the backup engine
    let mut engine = match BackupEngine::new(config) {
        Ok(eng) => eng,
        Err(e) => {
            eprintln!("❌ Engine initialization error: {e}");
            process::exit(1);
        }
    };

    // Step 3: Run the backup
    match engine.run() {
        Ok(report) => {
            if !report.skipped {
                println!("\n✅ Backup completed successfully!");
            }
        }
        Err(e) => {
            eprintln!("\n❌ Backup failed: {e}");
            process::exit(1);
        }
    }
}
```

## How It Works (Data Flow)

```
backup_config.toml
        │
        ▼
┌─────────────────┐    parse + validate    ┌──────────────┐
│  BackupConfig    │◄──────────────────────│  TOML file   │
│  (config.rs)     │                        └──────────────┘
└────────┬────────┘
         │
         ▼
┌─────────────────┐    load / create       ┌───────────────────┐
│  BackupEngine    │◄─────────────────────│  .manifest.json   │
│  (backup.rs)     │                        │  (manifest.rs)    │
└────────┬────────┘                        └───────────────────┘
         │
         ├─── 1. Scan source dirs (recursive, with glob filters)
         ├─── 2. SHA-256 hash each file
         ├─── 3. Compare hashes against manifest → ChangeSet
         ├─── 4. Copy only changed files to timestamped backup dir
         ├─── 5. Update manifest with new hashes
         ├─── 6. Enforce retention policy (prune old backups)
         │
         ▼
┌─────────────────┐
│  BackupReport    │──→ stdout summary
└─────────────────┘

Backup directory layout:
/tmp/backups/
├── .manifest.json
├── daily-project-backup_full_20250101_120000/
│   ├── src/main.rs
│   └── docs/readme.md
├── daily-project-backup_incr_20250102_120000/
│   ├── src/lib.rs              ← only changed files
│   └── _deleted_files.log      ← tombstone list
└── daily-project-backup_incr_20250103_120000/
    └── src/main.rs
```

## Key Design Decisions

| Concern | Approach |
|---|---|
| **Change detection** | SHA-256 content hashing (not just timestamps) |
| **Full vs incremental** | Auto-triggers full after N incrementals (`max_incremental_per_full`) |
| **Glob filtering** | Custom recursive matcher supporting `*` and `?` |
| **Config defaults** | `serde(default)` + named default functions for every optional field |
| **Validation** | Runs after parse — checks paths exist, patterns valid, ranges correct |
| **Error handling** | `thiserror` enum with contextual variants, unified `Result<T>` alias |
| **Retention** | Prunes oldest backups exceeding configured limits after each run |
| **Manifest** | JSON-serialized `HashMap<PathBuf, FileRecord>` persisted between runs |
